from typing import Callable

from commands3.custom.asyncgen_noco import Command, co, StateMachine

from mechanisms.arm import Arm
from mechanisms.elevator import Elevator
from mechanisms.intake import Intake


class Superstructure:
    def __init__(self, plant, wants_intake: Callable[[], bool], wants_score: Callable[[], bool]):
        self.plant = plant
        self.elevator = Elevator(plant)
        self.arm = Arm(plant)
        self.intake = Intake(plant)
